const rawMarkdown = $('8️⃣Rewrite Resume').item.json.output || '';
const email = $('On form submission').item.json.Email || '';  // ✅ pulling original email

function convertMarkdownToHtml(markdown) {
  return markdown
    .replace(/^### (.*$)/gim, '<h3>$1</h3>')
    .replace(/^## (.*$)/gim, '<h2>$1</h2>')
    .replace(/^# (.*$)/gim, '<h1>$1</h1>')
    .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/gim, '<em>$1</em>')
    .replace(/---/g, '<hr>')
    .replace(/\n{2,}/g, '</p><p>')
    .replace(/\n/g, '<br>');
}

const html = `<p>${convertMarkdownToHtml(rawMarkdown)}</p>`;

return [{
  json: {
    tailored_resume_html: html,
    email: email  // ✅ include email in output
  }
}];

const rawMarkdown = $('🔥Write Cover Letter').item.json.output || '';

function convertMarkdownToHtml(markdown) {
  return markdown
    .replace(/^### (.*$)/gim, '<h3>$1</h3>')
    .replace(/^## (.*$)/gim, '<h2>$1</h2>')
    .replace(/^# (.*$)/gim, '<h1>$1</h1>')
    .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/gim, '<em>$1</em>')
    .replace(/---/g, '<hr>')
    .replace(/\n{2,}/g, '</p><p>')
    .replace(/\n/g, '<br>');
}

const html = `<p>${convertMarkdownToHtml(rawMarkdown)}</p>`;

return [{
  json: {
    cover_letter_html: html
  }
}];

const inputs = $input.all();

const mergedInput = inputs[0]?.json || {};
const jobInfo = inputs[1]?.json || {};

// Try to find email: either from earlier or deep search
let email = mergedInput.email || jobInfo.email || jobInfo.Email;

// Fallback: try getting it from form submission node directly
if (!email) {
  const form = $('On form submission').item.json;
  email = form.Email || '';
}

return [{
  json: {
    job_title: jobInfo.job_title || '',
    job_url: jobInfo.job_url || '',
    company: jobInfo.company || '',
    resume_html: mergedInput.tailored_resume_html || mergedInput.resume_html || '',
    cover_letter_html: mergedInput.cover_letter_html || '',
    email: email  // ✅ safely passed
  }
}];

